package com.tripmateai.service.impl;
import com.tripmateai.dto.request.itinerary.*; import com.tripmateai.dto.response.itinerary.ItineraryResponse; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.ItineraryMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.ItineraryService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class ItineraryServiceImpl implements ItineraryService {private final TripRepository trips;private final ItineraryRepository itineraries; private User user(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal x))throw new UnauthorizedException("Authentication required");return x.user();} private Trip trip(Long id){return trips.findByIdAndUser(id,user()).orElseThrow(()->trips.existsById(id)?new UnauthorizedException("You do not have access to this trip"):new ResourceNotFoundException("Trip not found"));} private Itinerary item(Long tripId,Long id){return itineraries.findByIdAndTrip(id,trip(tripId)).orElseThrow(()->new ResourceNotFoundException("Itinerary not found"));} public ItineraryResponse create(Long tripId,CreateItineraryRequest r){if(!Objects.equals(r.tripId(),tripId))throw new BadRequestException("Trip ID must match path");var t=trip(tripId);if(itineraries.existsByTripAndDayNumber(t,r.dayNumber()))throw new BadRequestException("An itinerary already exists for this day");var i=new Itinerary();i.setTrip(t);i.setDayNumber(r.dayNumber());i.setTitle(r.title());i.setDescription(r.description());return ItineraryMapper.toResponse(itineraries.save(i));} @Transactional(readOnly=true) public List<ItineraryResponse> list(Long tripId){return itineraries.findByTripOrderByDayNumberAsc(trip(tripId)).stream().map(ItineraryMapper::toResponse).toList();} @Transactional(readOnly=true) public ItineraryResponse get(Long tripId,Long id){return ItineraryMapper.toResponse(item(tripId,id));} public ItineraryResponse update(Long tripId,Long id,UpdateItineraryRequest r){var i=item(tripId,id);if(!i.getDayNumber().equals(r.dayNumber())&&itineraries.existsByTripAndDayNumber(i.getTrip(),r.dayNumber()))throw new BadRequestException("An itinerary already exists for this day");i.setDayNumber(r.dayNumber());i.setTitle(r.title());i.setDescription(r.description());return ItineraryMapper.toResponse(itineraries.save(i));} public void delete(Long tripId,Long id){itineraries.delete(item(tripId,id));}}
